PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?spouse ?spouseName (COALESCE(?bpPlace, ?dboPlace) AS ?birthPlace)
WHERE {
  dbr:Coretta_Scott_King dbp:spouse ?spouse .
  OPTIONAL { ?spouse rdfs:label ?spouseName . FILTER (lang(?spouseName) = "en") }
  OPTIONAL { ?spouse dbp:birthPlace ?bpPlace . }
  OPTIONAL { ?spouse dbo:birthPlace ?dboPlace . }
}
LIMIT 100

